/* Per-thread copies of a few dword globals, for simulating matches on several threads (par.c).
 *
 * Every instruction that addresses one of the globals in tls_sites.h (generated by tls_sites.py: the
 * RNG state of random(n) and the CRT's rand, and scratch/cache dwords the simulation writes) becomes a
 * jump to a thunk that runs the same instruction with an fs: override and the global's TEB slot
 * (TlsSlots, fs:[0xe10 + 4*index]) in place of its address, then jumps back. Flags, registers and the
 * instruction's semantics are unchanged; each thread just sees its own copy. 
 */

#include <string.h>

#include "cmspeed.h"
#include "tls_sites.h"

static DWORD slot_index[TLS_NGLOBALS];
static int installed;

static DWORD *teb_slot(DWORD index)
{
    return (DWORD *)((BYTE *)NtCurrentTeb() + 0xe10 + 4 * index);
}

DWORD *tls_ptr(DWORD global)
{
    if (installed)
        for (int i = 0; i < TLS_NGLOBALS; i++)
            if (tls_globals[i] == global)
                return teb_slot(slot_index[i]);
    return (DWORD *)global;
}

int install_tls_globals(void)
{
    for (int i = 0; i < TLS_NGLOBALS; i++) {
        slot_index[i] = TlsAlloc();
        if (slot_index[i] >= 64) {
            logmsg("tls: TLS index %lu is beyond the TEB's inline slots", slot_index[i]);
            return 0;
        }
        *teb_slot(slot_index[i]) = *(DWORD *)tls_globals[i]; /* the game thread keeps the current value */
    }
    BYTE *thunks = VirtualAlloc(NULL, TLS_NSITES * 24, MEM_COMMIT, PAGE_EXECUTE_READWRITE);
    if (!thunks)
        return 0;
    for (int i = 0; i < TLS_NSITES; i++) {
        const struct tls_site *s = &tls_sites[i];
        BYTE *t = thunks + i * 24;
        t[0] = 0x64; /* fs: */
        memcpy(t + 1, s->bytes, s->len);
        *(DWORD *)(t + 1 + s->disp) = 0xe10 + 4 * slot_index[s->global];
        t[1 + s->len] = 0xe9;
        *(DWORD *)(t + 2 + s->len) = (s->addr + s->len) - ((DWORD)t + 6 + s->len);
        BYTE repl[12];
        memset(repl, 0x90, sizeof repl);
        repl[0] = 0xe9;
        *(DWORD *)(repl + 1) = (DWORD)t - (s->addr + 5);
        if (!patch_bytes(s->addr, s->bytes, repl, s->len))
            return 0;
    }
    installed = 1;
    logmsg("tls: %d globals per thread, %d instructions rewritten", TLS_NGLOBALS, TLS_NSITES);
    return 1;
}
